events.command:
/bin/bash -lc "awk -F '\\t' '
{
 split("'$6,a,"|"); g=a[6]; key=$1 SUBSEP g;
 if($10 > score[key]) {score[key]=$10; qs[key]=$3; qe[key]=$4; strand[key]=$5; target[key]=$6}
 genes[$1 SUBSEP g]=1; qlen[$1]=$2
}
END{
 for(k in score){split(k,z,SUBSEP); q=z[1]; g=z[2]; if(score[k]>=100) print q,qlen[q],g,qs[k],qe[k],score[k],target[k]}
}'"' contigs_vs_gencode.paf | sort -k1,1 -k4,4n > contig_gene_hits.tsv
awk '{q="'$1; if(q!=prev && prev!=""){if(n>=2) print prev,ql,n,desc}; if(q!=prev){n=0;desc="";ql=$2}; n++; desc=desc " " $3 ":" $4 "-" $5 ":" $6; prev=q} END{if(n>=2) print prev,ql,n,desc}'"' contig_gene_hits.tsv | sort -k3,3nr | sed -n '1,100p'"

